// Prueba de la infraestructura de pruebas: si un helper se rompe (p. ej. cambia un selector de Moodle),
// esto falla primero y con un mensaje claro, antes que cualquier prueba de spec.
import { test, expect } from '@playwright/test';
import { login, abrirQuiz, botonIntento, elegir, escribirEnsayo, siguientePagina, enviarIntento, filaResumen } from './helpers';

test.describe('[HUMO] helpers de prueba', () => {
  test.skip(({ isMobile }) => isMobile, 'La infraestructura se valida una vez, en escritorio');

  test('[HUMO] estudiante completa el examen con ensayo y el profesor lo ve pendiente de calificar', async ({ page }) => {
    await login(page, 'estudiante12');
    await abrirQuiz(page);
    await botonIntento(page).click();
    await elegir(page, 1, 'One');
    await elegir(page, 2, 'True');
    await siguientePagina(page);
    await elegir(page, 3, 'One');
    await elegir(page, 4, 'True');
    await siguientePagina(page);
    await elegir(page, 5, 'True');
    await escribirEnsayo(page, 6, 'Una rana saltó al estanque.');
    await enviarIntento(page);
    await expect(filaResumen(page, 'Status')).toHaveText('Finished');
    // Hecho verificado en 5.3: con un ensayo respondido la nota queda pendiente y no hay fila "Marks" ni "Feedback".
    await expect(filaResumen(page, 'Grade')).toHaveText('Not yet graded');

    await login(page, 'profesor');
    const cmid = await abrirQuiz(page);
    await page.goto(`/mod/quiz/report.php?id=${cmid}&mode=grading`);
    await expect(page.getByRole('cell', { name: /HIS-2 Ensayo/ })).toBeVisible();
  });
});

import { defineConfig, devices } from '@playwright/test';

// Corre SIEMPRE dentro de mcr.microsoft.com/playwright:v1.64.1-noble (ver factory/lib/suite.mjs),
// para que el renderizado (fuentes, antialiasing) sea idéntico en cualquier máquina.
const OUT = process.env.QA_OUT || 'test-results/ultima';

export default defineConfig({
  testDir: '.',
  testMatch: ['factory/regresion/**/*.spec.ts', 'salidas/*/pruebas/**/*.spec.ts'],
  // Estado compartido (un solo Moodle): secuencial y determinista.
  workers: 1,
  fullyParallel: false,
  // Sin reintentos: un reintento automático esconde pruebas inestables. Si algo es flaky, se arregla.
  retries: 0,
  timeout: 90_000,
  outputDir: `${OUT}/artefactos`,
  reporter: [
    ['list'],
    ['junit', { outputFile: `${OUT}/funcional.xml` }],
    ['json', { outputFile: `${OUT}/resultados.json` }],
    ['html', { outputFolder: `${OUT}/visual`, open: 'never' }],
  ],
  // Líneas base versionadas en el repo, un archivo por pantalla y viewport.
  snapshotPathTemplate: 'visual/lineas-base/{arg}--{projectName}{ext}',
  expect: {
    toHaveScreenshot: {
      // threshold: tolerancia de color POR PIXEL (YIQ, 0..1). 0.2 absorbe antialiasing de fuentes.
      // maxDiffPixelRatio: fracción de pixeles distintos tolerada en la pantalla. 0.002 = 0,2 %.
      //   Una fila nueva, un botón desplazado o un color de tema cambiado superan eso con holgura;
      //   el ruido de subpixel queda por debajo. Criterio y mediciones en cobertura.md.
      threshold: 0.2,
      maxDiffPixelRatio: 0.002,
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
    },
  },
  use: {
    baseURL: process.env.BASE_URL || 'http://localhost:8090',
    locale: 'en-US',
    timezoneId: 'America/Guatemala',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [
    { name: 'escritorio', use: { ...devices['Desktop Chrome'], viewport: { width: 1366, height: 900 } } },
    { name: 'movil', use: { ...devices['Pixel 7'] } },
  ],
});

