1	// Ejecuta Playwright dentro del contenedor oficial (renderizado idéntico entre máquinas) y normaliza resultados.
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { RAIZ, DC, sh } from './util.mjs';
5	
6	/**
7	 * @param archivos  rutas de .spec.ts (relativas a la raíz) o [] para toda la suite
8	 * @param out       carpeta de salida relativa a la raíz (allí quedan funcional.xml, resultados.json, visual/)
9	 * @param opciones  { crearLineasBaseFaltantes, grep }
10	 */
11	export function correrPruebas(archivos, out, { crearLineasBaseFaltantes = false, grep } = {}) {
12	  fs.rmSync(path.join(RAIZ, out, 'artefactos'), { recursive: true, force: true });
13	  const flags = [
14	    // Solo se crean líneas base que NO existen (pantallas nuevas). Una línea base existente nunca se
15	    // sobrescribe desde el pipeline: eso es una decisión humana (factory/cli.mjs aprobar-linea-base).
16	    crearLineasBaseFaltantes ? '--update-snapshots=missing' : '--update-snapshots=none',
17	    grep ? `--grep '${grep}'` : '',
18	  ].join(' ');
19	  const cmd = `${DC} --profile qa run --rm -T -e QA_OUT=${out} qa npx playwright test ${archivos.join(' ')} ${flags}`;
20	  const r = sh(cmd, { timeout: 60 * 60_000 });
21	  const resultados = leerResultados(path.join(RAIZ, out, 'resultados.json'));
22	  return { code: r.code, salida: (r.out + r.err).replace(/^.*Container .*$/gm, '').trim(), resultados };
23	}
24	
25	/** Aplana el reporte JSON de Playwright: [{titulo, archivo, proyecto, estado, error, tags, anotaciones}] */
26	export function leerResultados(ruta) {
27	  if (!fs.existsSync(ruta)) return [];
28	  const json = JSON.parse(fs.readFileSync(ruta, 'utf8'));
29	  const out = [];
30	  const recorrer = (suite, prefijo) => {
31	    for (const s of suite.suites || []) recorrer(s, [...prefijo, s.title].filter(Boolean));
32	    for (const spec of suite.specs || []) {
33	      for (const t of spec.tests || []) {
34	        const res = t.results?.[t.results.length - 1] || {};
35	        out.push({
36	          titulo: [...prefijo.slice(1), spec.title].join(' › '),
37	          archivo: spec.file,
38	          proyecto: t.projectName,
39	          estado: res.status || t.status, // passed | failed | timedOut | skipped | interrupted
40	          error: res.error?.message?.slice(0, 2500) || null,
41	          anotaciones: (t.annotations || []).map((a) => `${a.type}: ${a.description || ''}`),
42	        });
43	      }
44	    }
45	  };
46	  for (const s of json.suites || []) recorrer(s, [s.title]);
47	  return out;
48	}
49	
50	export function resumen(resultados) {
51	  const c = { passed: 0, failed: 0, skipped: 0, otros: 0 };
52	  for (const r of resultados) {
53	    if (r.estado === 'passed') c.passed++;
54	    else if (r.estado === 'skipped') c.skipped++;
55	    else if (['failed', 'timedOut', 'interrupted'].includes(r.estado)) c.failed++;
56	    else c.otros++;
57	  }
58	  return c;
59	}
60	
61	/** Contexto de fallo para la IA correctora: error + snapshot ARIA de la página al fallar (error-context.md). */
62	export function contextoFallos(out, resultados, max = 6) {
63	  const fallidas = resultados.filter((r) => !['passed', 'skipped'].includes(r.estado)).slice(0, max);
64	  const dirArt = path.join(RAIZ, out, 'artefactos');
65	  const contextos = fs.existsSync(dirArt)
66	    ? fs.readdirSync(dirArt).map((d) => path.join(dirArt, d, 'error-context.md')).filter((f) => fs.existsSync(f))
67	    : [];
