9	//                                            [--plan <plan.json>] [--salida <honestidad.log>]
10	import fs from 'node:fs';
11	import path from 'node:path';
12	import crypto from 'node:crypto';
13	import { execSync } from 'node:child_process';
14	import { fileURLToPath } from 'node:url';
15	import { analizarArchivo, idPrueba } from './analisis.mjs';
16	
17	const RAIZ = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
18	const REF = process.env.HONESTIDAD_REF || 'main';
19	const MANIFIESTO = 'factory/honestidad/manifiesto.json';
20	const APROBACIONES = 'visual/lineas-base/APROBACIONES.json';
21	const CONFIG = 'playwright.config.ts';
22	
23	const arg = (n) => { const i = process.argv.indexOf(n); return i > 0 ? process.argv[i + 1] : null; };
24	const enRef = (p) => { try { return execSync(`git show ${REF}:${p}`, { cwd: RAIZ, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); } catch { return null; } };
25	const json = (s, def) => { try { return s ? JSON.parse(s) : def; } catch { return def; } };
26	const sha = (f) => crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
27	
28	function listarPruebas() {
29	  const out = [];
30	  const recorrer = (d) => {
31	    const abs = path.join(RAIZ, d);
32	    if (!fs.existsSync(abs)) return;
33	    for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
34	      const rel = path.join(d, e.name);
35	      if (e.isDirectory() && e.name !== 'node_modules') recorrer(rel);
36	      else if (e.name.endsWith('.spec.ts')) out.push(rel);
37	    }
38	  };
39	  recorrer('factory/regresion');
40	  for (const s of fs.existsSync(path.join(RAIZ, 'salidas')) ? fs.readdirSync(path.join(RAIZ, 'salidas')) : []) recorrer(`salidas/${s}/pruebas`);
41	  return out.sort();
42	}
43	
44	export function construirManifiesto() {
45	  const pruebas = {};
46	  const omisiones = {};
47	  for (const f of listarPruebas()) {
48	    const a = analizarArchivo(f, fs.readFileSync(path.join(RAIZ, f), 'utf8'));
49	    for (const p of a.pruebas) pruebas[idPrueba(p)] = { asserts: p.asserts, fuertes: p.fuertes, soft: p.soft, matchers: p.matchers, capturas: p.capturas, mascaras: p.mascaras, opcionesCaptura: p.opcionesCaptura, modificador: p.modificador, tags: p.tags };
50	    if (a.omisiones.length) omisiones[f] = a.omisiones.map((o) => o.texto);
51	  }
52	  const cfg = fs.readFileSync(path.join(RAIZ, CONFIG), 'utf8');
53	  return { pruebas, omisiones, umbralVisual: umbral(cfg) };
54	}
