29	use core_question\output\view_banks;
30	
31	require_once(__DIR__ . '/../config.php');
32	
33	global $CFG, $PAGE, $OUTPUT;
34	
35	$courseid = required_param('courseid', PARAM_INT);
36	$createdefault = optional_param('createdefault', false, PARAM_BOOL);
37	$course = get_course($courseid);
38	$coursecontext = context_course::instance($course->id);
39	
40	require_login($course, false);
41	$canmanage = has_capability('moodle/course:manageactivities', \context_course::instance($course->id));
42	
43	if (empty(question_bank_helper::get_activity_types_with_shareable_questions())) {
44	    throw new moodle_exception('disabledbanks', 'question');
45	}
46	
47	$allcaps = array_merge(question_edit_contexts::$caps['editq'], question_edit_contexts::$caps['categories']);
48	$sharedbanks = question_bank_helper::get_activity_instances_with_shareable_questions([$course->id], [], $allcaps);
49	$privatebanks = question_bank_helper::get_activity_instances_with_private_questions([$course->id], [], $allcaps);
50	
51	if (!$canmanage && empty($sharedbanks)) {
52	    // Only allow non-managing users access to this page if they can access at least 1 activity with shared questions.
53	    // If they can access activities with private questions (such as quiz) they can be accessed elsewhere on the course.
54	    throw new \core\exception\moodle_exception('nobankpermissions', 'question');
55	}
56	
57	$pageurl = question_bank_helper::get_url_for_qbank_list($course->id);
58	$PAGE->set_url($pageurl);
59	$PAGE->add_body_class('limitedwidth');
60	$PAGE->set_heading(format_string($course->fullname, true, ['context' => $coursecontext]));
61	$PAGE->set_title(get_string('questionbank_plural', 'question'));
62	
63	if ($canmanage && $createdefault) {
64	    require_sesskey();
65	    question_bank_helper::create_default_open_instance(
66	        $course,
67	        question_bank_helper::get_bank_name_string('defaultbank', 'core_question', ['coursename' => $course->fullname]),
68	    );
69	    \core\notification::add(get_string('defaultcreated', 'question'), \core\notification::SUCCESS);
70	    redirect($pageurl);
71	}
72	
73	$output = $PAGE->get_renderer('core_question', 'bank');
74	
75	echo $output->header();
76	if (!question_bank_helper::has_bank_migration_task_completed_successfully()) {
77	    $defaultactivityname = question_bank_helper::get_default_question_bank_activity_name();
78	    echo $OUTPUT->notification(get_string('transfernotfinished', 'mod_' . $defaultactivityname),
79	        \core\output\notification::NOTIFY_WARNING
80	    );
81	}
82	echo $output->render(new view_banks($sharedbanks, $privatebanks, $course));
83	echo $output->footer();
