15	// along with Moodle.  If not, see <http://www.gnu.org/licenses/>.
16	/**
17	 * Page for editing questions.
18	 *
19	 * @package    qbank_editquestion
20	 * @copyright  1999 onwards Martin Dougiamas {@link http://moodle.com}
21	 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
22	 */
23	
24	require_once(__DIR__ . '/../../../config.php');
25	require_once(__DIR__ . '/../../editlib.php');
26	require_once($CFG->libdir . '/filelib.php');
27	require_once($CFG->libdir . '/formslib.php');
28	
29	// Read URL parameters telling us which question to edit.
30	$id = optional_param('id', 0, PARAM_INT); // Question id.
31	$makecopy = optional_param('makecopy', 0, PARAM_BOOL);
32	$qtype = optional_param('qtype', '', PARAM_COMPONENT);
33	$categoryid = optional_param('category', 0, PARAM_INT);
34	$cmid = required_param('cmid', PARAM_INT);
35	$wizardnow = optional_param('wizardnow', '', PARAM_ALPHA);
36	$originalreturnurl = optional_param('returnurl', 0, PARAM_LOCALURL);
37	$appendqnumstring = optional_param('appendqnumstring', '', PARAM_ALPHA);
38	$inpopup = optional_param('inpopup', 0, PARAM_BOOL);
39	$mdlscrollto = optional_param('mdlscrollto', 0, PARAM_INT);
40	
41	\core_question\local\bank\helper::require_plugin_enabled('qbank_editquestion');
42	
43	$url = new moodle_url('/question/bank/editquestion/question.php');
44	if ($id !== 0) {
45	    $url->param('id', $id);
46	}
47	if ($makecopy) {
48	    $url->param('makecopy', $makecopy);
49	}
50	if ($qtype !== '') {
51	    $url->param('qtype', $qtype);
52	}
53	if ($categoryid !== 0) {
54	    $url->param('category', $categoryid);
55	}
56	if ($cmid !== 0) {
57	    $url->param('cmid', $cmid);
58	}
59	if ($wizardnow !== '') {
60	    $url->param('wizardnow', $wizardnow);
61	}
62	if ($originalreturnurl !== 0) {
63	    $url->param('returnurl', $originalreturnurl);
64	}
65	if ($appendqnumstring !== '') {
66	    $url->param('appendqnumstring', $appendqnumstring);
67	}
68	if ($inpopup !== 0) {
69	    $url->param('inpopup', $inpopup);
70	}
71	if ($mdlscrollto) {
72	    $url->param('mdlscrollto', $mdlscrollto);
73	}
74	$PAGE->set_url($url);
75	
76	$questionbankurl = new moodle_url('/question/edit.php', ['cmid' => $cmid]);
77	
78	navigation_node::override_active_url($questionbankurl);
79	
80	if ($originalreturnurl) {
81	    if (strpos($originalreturnurl, '/') !== 0) {
82	        throw new coding_exception("returnurl must be a local URL starting with '/'. $originalreturnurl was given.");
83	    }
84	    $returnurl = new moodle_url($originalreturnurl);
85	} else {
86	    $returnurl = $questionbankurl;
87	}
88	if ($mdlscrollto) {
89	    $returnurl->param('mdlscrollto', $mdlscrollto);
90	}
91	
92	list($module, $cm) = get_module_from_cmid($cmid);
93	require_login($cm->course, false, $cm);
94	$thiscontext = context_module::instance($cmid);
95	
96	$contexts = new core_question\local\bank\question_edit_contexts($thiscontext);
97	$PAGE->set_pagelayout('admin');
98	$PAGE->set_show_navigation_footer(false);
99	
100	if (optional_param('addcancel', false, PARAM_BOOL)) {
101	    redirect($returnurl);
102	}
103	
104	if ($id) {
105	    if (!$question = $DB->get_record('question', array('id' => $id))) {
106	        throw new moodle_exception('questiondoesnotexist', 'question', $returnurl);
107	    }
108	    get_question_options($question, true);
109	
110	} else if ($categoryid && $qtype) { // Only for creating new questions.
111	    $question = new stdClass();
112	    $question->category = $categoryid;
113	    $question->qtype = $qtype;
114	    $question->createdby = $USER->id;
115	
116	    // Check that users are allowed to create this question type at the moment.
117	    if (!question_bank::qtype_enabled($qtype)) {
118	        throw new moodle_exception('cannotenable', 'question', $returnurl, $qtype);
119	    }
120	
121	} else if ($categoryid) {
122	    // Category, but no qtype. They probably came from the addquestion.php
123	    // script without choosing a question type. Send them back.
124	    $addurl = new moodle_url('/question/bank/editquestion/addquestion.php', $url->params());
125	    $addurl->param('validationerror', 1);
126	    redirect($addurl);
127	
128	} else {
129	    throw new moodle_exception('notenoughdatatoeditaquestion', 'question', $returnurl);
130	}
131	
132	// If we get to the editing page from somewhere outside the question bank (such as the quiz) while migration is still
133	// pending, redirect back with a warning.
134	if (!\core_question\local\bank\question_bank_helper::has_bank_migration_task_completed_successfully()) {
135	    $defaultactivityname = \core_question\local\bank\question_bank_helper::get_default_question_bank_activity_name();
136	    redirect(
137	        $returnurl,
138	        get_string('transfernotfinished', 'mod_' . $defaultactivityname),
139	        messagetype: \core\output\notification::NOTIFY_WARNING,
140	    );
141	}
142	
143	$qtypeobj = question_bank::get_qtype($question->qtype);
144	
145	if (isset($question->categoryobject)) {
146	    $category = $question->categoryobject;
147	} else {
148	    // Validate the question category.
149	    if (!$category = $DB->get_record('question_categories', array('id' => $question->category))) {
150	        throw new moodle_exception('categorydoesnotexist', 'question', $returnurl);
151	    }
152	}
153	
154	// Check permissions.
155	$question->formoptions = new stdClass();
156	
157	$categorycontext = context::instance_by_id($category->contextid);
158	$question->contextid = $category->contextid;
159	$addpermission = has_capability('moodle/question:add', $categorycontext);
160	
161	if ($id) {
162	    $question->formoptions->canedit = question_has_capability_on($question, 'edit');
163	    $question->formoptions->canmove = $addpermission && question_has_capability_on($question, 'move');
164	    $question->formoptions->cansaveasnew = $addpermission &&
165	            (question_has_capability_on($question, 'view') || $question->formoptions->canedit);
166	    $question->formoptions->repeatelements = $question->formoptions->canedit || $question->formoptions->cansaveasnew;
167	    $formeditable = $question->formoptions->canedit || $question->formoptions->cansaveasnew || $question->formoptions->canmove;
168	    if (!$formeditable) {
169	        question_require_capability_on($question, 'view');
170	    }
171	    $question->beingcopied = false;
172	    if ($makecopy) {
173	        // If we are duplicating a question, add some indication to the question name.
174	        $question->name = get_string('questionnamecopy', 'question', $question->name);
175	        $question->idnumber = isset($question->idnumber) ?
176	            core_question_find_next_unused_idnumber($question->idnumber, $category->id) : '';
177	        $question->beingcopied = true;
178	    }
179	
180	} else { // Creating a new question.
181	    $question->formoptions->canedit = question_has_capability_on($question, 'edit');
182	    $question->formoptions->canmove = (question_has_capability_on($question, 'move') && $addpermission);
183	    $question->formoptions->cansaveasnew = false;
184	    $question->formoptions->repeatelements = true;
185	    $formeditable = true;
186	    require_capability('moodle/question:add', $categorycontext);
187	}
188	$question->formoptions->mustbeusable = (bool) $appendqnumstring;
189	
190	// Validate the question type.
191	$PAGE->set_pagetype('question-type-' . $question->qtype);
192	
193	// Create the question editing form.
194	if ($wizardnow !== '') {
195	    $mform = $qtypeobj->next_wizard_form('question.php', $question, $wizardnow, $formeditable);
196	} else {
197	    $mform = $qtypeobj->create_editing_form('question.php', $question, $category, $contexts, $formeditable);
198	}
199	$toform = fullclone($question); // Send the question object and a few more parameters to the form.
200	$toform->category = "{$category->id},{$category->contextid}";
201	$toform->mdlscrollto = $mdlscrollto;
202	if ($formeditable && $id) {
203	    $toform->categorymoveto = $toform->category;
204	}
205	
206	$toform->appendqnumstring = $appendqnumstring;
207	$toform->returnurl = $originalreturnurl;
208	$toform->makecopy = $makecopy;
209	$toform->idnumber = null;
210	if (!empty($question->id)) {
211	    $questionobject = question_bank::load_question($question->id);
212	    $toform->status = $questionobject->status;
213	    $toform->idnumber = $questionobject->idnumber;
214	} else {
215	    $toform->status = \core_question\local\bank\question_version_status::QUESTION_STATUS_READY;
216	}
217	if ($makecopy) {
218	    $toform->idnumber = core_question_find_next_unused_idnumber($toform->idnumber, $category->id);
219	}
220	if ($cm !== null) {
221	    $toform->cmid = $cm->id;
222	    $toform->courseid = $cm->course;
223	} else {
224	    $toform->courseid = $COURSE->id;
225	}
226	
227	$toform->inpopup = $inpopup;
228	
229	// Prepare custom fields data.
230	$customfieldhandler = qbank_customfields\customfield\question_handler::create();
231	$customfieldhandler->instance_form_before_set_data($toform);
232	
233	$mform->set_data($toform);
234	
235	if ($mform->is_cancelled()) {
236	    if ($inpopup) {
237	        close_window();
238	    } else {
239	        redirect($returnurl);
240	    }
241	
242	} else if ($fromform = $mform->get_data()) {
243	    // If we are saving as a copy, break the connection to the old question.
244	    if ($makecopy) {
245	        $question->id = 0;
246	        // Copies should not be hidden.
247	        $question->status = \core_question\local\bank\question_version_status::QUESTION_STATUS_READY;
248	    }
249	
250	    // If is will be added directly to a module send the module name to be referenced.
251	    if ($appendqnumstring && $cm) {
252	        $fromform->modulename = 'mod_' . $cm->modname;
253	    }
254	
255	    // Process the combination of usecurrentcat, categorymoveto and category form
256	    // fields, so the save_question method only has to consider $fromform->category.
257	    if (empty($fromform->usecurrentcat) && !empty($fromform->categorymoveto)) {
258	        $fromform->category = $fromform->categorymoveto;
259	    }
260	
261	    // If we are moving a question, check we have permission to move it from
262	    // whence it came (Where we are moving to is validated by the form).
263	    list($newcatid, $newcontextid) = explode(',', $fromform->category);
264	    if (!empty($question->id) && $newcatid != $question->categoryobject->id) {
265	        $contextid = $newcontextid;
266	        question_require_capability_on($question, 'move');
267	    } else {
268	        $contextid = $category->contextid;
269	    }
270	
271	    // Ensure we redirect back to the category the question is being saved into.
272	    $returnurl->param('category', $fromform->category);
273	
274	    // We are actually saving the question.
275	    if (!empty($question->id)) {
276	        question_require_capability_on($question, 'edit');
277	    } else {
278	        require_capability('moodle/question:add', context::instance_by_id($contextid));
279	        if (!empty($fromform->makecopy) && !$question->formoptions->cansaveasnew) {
280	            throw new moodle_exception('nopermissions', '', '', 'edit');
281	        }
282	    }
283	
284	    // If this is a new question and question defaults save is enabled, save defaults for user in user_preferences table.
285	    if (empty($question->id) && !empty($CFG->questiondefaultssave)) {
286	        $qtypeobj->save_defaults_for_new_questions($fromform);
287	    }
288	    $question = $qtypeobj->save_question($question, $fromform);
289	    if (isset($fromform->tags)) {
290	        // If we have any question context level tags then set those tags now.
291	        core_tag_tag::set_item_tags('core_question', 'question', $question->id,
292	                context::instance_by_id($contextid), $fromform->tags, 0);
293	    }
294	
295	    if (isset($fromform->coursetags)) {
296	        // If we have and course context level tags then set those now.
297	        core_tag_tag::set_item_tags('core_question', 'question', $question->id,
298	                context_course::instance($fromform->courseid), $fromform->coursetags, 0);
299	    }
300	
301	    // Update custom fields if there are any of them in the form.
302	    $customfieldhandler->instance_form_save($fromform);
303	
304	    // Purge this question from the cache.
305	    question_bank::notify_question_edited($question->id);
306	
307	    // If we are saving and continuing to edit the question.
308	    if (!empty($fromform->updatebutton)) {
309	        $url->param('id', $question->id);
310	        $url->remove_params('makecopy');
311	        redirect($url);
312	    }
313	
314	    if ($qtypeobj->finished_edit_wizard($fromform)) {
315	        if ($inpopup) {
316	            echo $OUTPUT->notification(get_string('changessaved'), '');
317	            close_window(3);
318	        } else {
319	            $returnurl->param('lastchanged', $question->id);
320	            if ($appendqnumstring) {
321	                $returnurl->param($appendqnumstring, $question->id);
322	                $returnurl->param('sesskey', sesskey());
323	                $returnurl->param('cmid', $cmid);
324	            }
325	            // Update the filter param to the updated category if the return have any.
326	            if (!empty($returnurl->param('filter'))) {
327	                $filter = json_decode($returnurl->param('filter'), true);
328	                if (isset($filter['category']['values'])) {
329	                    $filter['category']['values'][0] = $question->category;
330	                    $returnurl->param('filter', json_encode($filter));
331	                }
332	            }
333	            redirect($returnurl);
334	        }
335	
336	    } else {
337	        $nexturlparams = [
338	                'returnurl' => $originalreturnurl,
339	                'appendqnumstring' => $appendqnumstring,
340	                'mdlscrollto' => $mdlscrollto,
341	        ];
342	        if (isset($fromform->nextpageparam) && is_array($fromform->nextpageparam)) {
343	            // Useful for passing data to the next page which is not saved in the database.
344	            $nexturlparams += $fromform->nextpageparam;
345	        }
346	        $nexturlparams['id'] = $question->id;
347	        $nexturlparams['wizardnow'] = $fromform->wizard;
348	        $nexturl = new moodle_url($url, $nexturlparams);
349	        if ($cmid) {
350	            $nexturl->param('cmid', $cmid);
351	        } else {
352	            $nexturl->param('courseid', $COURSE->id);
353	        }
354	        // Update the filter param to the updated category if the return url have any.
355	        if (!empty($nexturl->param('filter'))) {
356	            $filter = json_decode($nexturl->param('filter'), true);
357	            if (isset($filter['category']['values'])) {
358	                $filter['category']['values'][0] = $question->category;
359	                $nexturl->param('filter', json_encode($filter));
360	            }
361	        }
362	        redirect($nexturl);
363	    }
364	
365	}
366	
367	$streditingquestion = $qtypeobj->get_heading();
368	$PAGE->set_title($streditingquestion);
369	$PAGE->set_heading($COURSE->fullname);
370	$PAGE->activityheader->disable();
371	$PAGE->navbar->add($streditingquestion);
372	if ($PAGE->course->id == $SITE->id) {
373	    $PAGE->set_primary_active_tab('home');
374	}
375	
376	// Display a heading, question editing form and possibly some extra content needed for
377	// for this question type.
378	echo $OUTPUT->header();
379	$qtypeobj->display_question_editing_page($mform, $question, $wizardnow);
380	echo $OUTPUT->footer();
381

