72	if ($deleteselected && $confirm && confirm_sesskey()) {
73	    $deleteselected = required_param('deleteselected', PARAM_RAW);
74	    if ($questionlist = explode(',', $deleteselected)) {
75	        \qbank_deletequestion\helper::delete_questions($questionlist, $deleteall);
76	    }
77	    redirect($returnurl);
78	}
79	
80	echo $OUTPUT->header();
81	
82	if ($deleteselected) {
83	    // Make a list of all the questions that are selected.
84	    $rawquestions = $_REQUEST; // This code is called by both POST forms and GET links, so cannot use data_submitted.
85	    $questionlist = '';  // Comma separated list of ids of questions to be deleted.
86	    foreach ($rawquestions as $key => $value) {    // Parse input for question ids.
87	        if (preg_match('!^q([0-9]+)$!', $key, $matches)) {
88	            $key = $matches[1];
89	            $questionlist .= $key.',';
90	            question_require_capability_on((int)$key, 'edit');
91	        }
92	    }
93	    if (!$questionlist) { // No questions were selected.
94	        redirect($returnurl);
95	    }
96	    $questionlist = rtrim($questionlist, ',');
97	
98	    $deleteurl = new \moodle_url(
99	        '/question/bank/deletequestion/delete.php',
100	        [
101	            'deleteselected' => $questionlist,
102	            'deleteall' => $deleteall,
103	            'confirm' => true,
104	            'sesskey' => sesskey(),
105	            'returnurl' => $returnurl->out_as_local_url(false),
106	            'cmid' => $cmid,
107	        ],
108	    );
109	    $continue = new \single_button($deleteurl, get_string('delete'), 'post');
110	
111	    $questionids = explode(',', $questionlist);
112	    [$displayoptions, $message] = qbank_deletequestion\helper::get_delete_confirmation_message($questionids,
113	        $deleteall);
114	
115	    echo $OUTPUT->confirm($message, $continue, $returnurl, $displayoptions);
116	}
117	
118	echo $OUTPUT->footer();
