39	class delete_action extends question_action_base {
40	
41	    /**
42	     * @var string $strdelete
43	     */
44	    protected $strdelete;
45	
46	    /**
47	     * @var string $strrestore
48	     */
49	    protected $strrestore;
50	
51	    /**
52	     * Contains the url of the delete question page.
53	     * @var \moodle_url|string
54	     */
55	    public $deletequestionurl;
56	
57	    /**
58	     * Array of the return parameters.
59	     * @var array $returnparams
60	     */
61	    protected $returnparams;
62	
63	    public function init(): void {
64	        parent::init();
65	        $this->strdelete = get_string('delete');
66	        $this->strrestore = get_string('restore');
67	        $this->deletequestionurl = new \moodle_url('/question/bank/deletequestion/delete.php');
68	        $this->returnparams['cmid'] = $this->qbank->cm->id;
69	
70	        if (!empty($this->qbank->returnurl)) {
71	            $this->returnparams['returnurl'] = $this->qbank->returnurl;
72	        }
73	    }
74	
75	    public function get_menu_position(): int {
76	        return 2000;
77	    }
78	
79	    protected function get_url_icon_and_label(\stdClass $question): array {
80	        if (!question_has_capability_on($question, 'edit')) {
81	            return [null, null, null];
82	        }
83	        if ($question->status === question_version_status::QUESTION_STATUS_HIDDEN) {
84	            $hiddenparams = array(
85	                    'unhide' => $question->id,
86	                    'sesskey' => sesskey());
87	            $hiddenparams = array_merge($hiddenparams, $this->returnparams);
88	            $url = new \moodle_url($this->deletequestionurl, $hiddenparams);
89	            return [$url, 't/restore', $this->strrestore];
90	        } else {
91	            $deleteparams = array(
92	                    'deleteselected' => $question->id,
93	                    'q' . $question->id => 1,
94	                    'sesskey' => sesskey());
95	            $deleteparams = array_merge($deleteparams, $this->returnparams);
96	            if (!$this->qbank->is_listing_specific_versions()) {
97	                $deleteparams['deleteall'] = 1;
98	            }
99	            $url = new \moodle_url($this->deletequestionurl, $deleteparams);
100	            return [$url, 't/delete', $this->strdelete];
101	        }
102	    }
103	
104	    /**
105	     * Override method to get url and label for delete action to add the text-danger class.
106	     *
107	     * @param \stdClass $question
108	     * @return \action_menu_link|null
109	     */
110	    public function get_action_menu_link(\stdClass $question): ?\action_menu_link {
111	        $deletelink = parent::get_action_menu_link($question);
112	        if ($deletelink !== null) {
113	            $confirmurl = new url($deletelink->url, ['sesskey' => sesskey(), 'confirm' => true]);
114	            $deletelink->add_class('text-danger');
115	            $deleteallversions = $confirmurl->param('deleteall') ?? false;
116	            [$confirmtitle, $confirmessage] = helper::get_delete_confirmation_message([$question->id], $deleteallversions);
117	            $deletelink->attributes['data-confirmation'] = 'modal';
118	            $deletelink->attributes['data-confirmation-type'] = 'delete';
119	            $deletelink->attributes['data-confirmation-title'] = $confirmtitle['confirmtitle'];
120	            $deletelink->attributes['data-confirmation-content'] = $confirmessage;
121	            $deletelink->attributes['data-confirmation-destination'] = $confirmurl->out(false);
122	            $deletelink->attributes['data-confirmation-yes-button-str'] = json_encode(['delete', 'core']);
123	        }
124	        return $deletelink;
125	    }
126	}
