81	if (data_submitted() && confirm_sesskey()) {
82	    if (optional_param('submit', false, PARAM_BOOL) && question_engine::is_manual_grade_in_range($attemptobj->get_uniqueid(), $slot)) {
83	        $transaction = $DB->start_delegated_transaction();
