21	/**
22	 * Bank switcher module for switching between question banks.
23	 *
24	 * The BankSwitcher class is used to display the bank switching UI in an existing Modal. This can either be a new Modal
25	 * created for the purpose, or an existing modal, in which case it will replace the existing title, body and footer.
26	 *
27	 * When a new bank is selected, it will emit a custom `bankSwitched` event on the modal's DOM element,
28	 * with the cmid of the selected bank in `event.details.cmid`. For example:
29	 *
30	 * const modal = Modal.create(...);
31	 * const switcher = new BankSwitcher();
32	 * switcher.show(modal, courseId, cmId);
33	 * modal.getModal().get(0).addEventListener('bankSwitched', (e) => window.console.log(e.details.cmid));
34	 *
35	 * @module     core_question/bank_switcher
36	 * @copyright  2025 Catalyst IT Europe Ltd.
37	 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
38	 */
39	
40	const SELECTORS = {
41	    ANCHOR: 'a[data-newmodid]',
42	    AUTOCOMPLETE_SELECTION: '.search-banks .form-autocomplete-selection',
43	    BANK_SEARCH: '#searchbanks',
44	    BANK_SWITCHER: '.bank-switcher',
45	    GO_BACK_BUTTON: 'button[data-action="go-back"]',
46	    MODAL: 'div[data-region="modal"]',
47	};
48	
49	export default class BankSwitcher {
50	    /**
51	     * Show the bank switcher.
52	     *
53	     * This will replace the content of the given modal with the bank switcher, and emit a bankChanged event on the modal
54	     * when a bank is selected (either a new bank, or the current one again).
55	     *
56	     * @param {Modal} modal The modal to display the switcher within.
57	     * @param {Number} courseId The course ID to display banks from.
58	     * @param {Number} contextId The context the bank switcher is being displayed in, for text filters.
59	     * @param {Number} currentCmId The cmid of the currently selected question bank.
60	     * @param {Number} activityCmId The cmid of activity we are currently in (if any).
61	     * @return {Promise<void>} Resolves once the switcher has finished displaying.
62	     */
63	    async show(modal, courseId, contextId, currentCmId = null, activityCmId = null) {
64	        if (!courseId) {
65	            throw new Error('courseId is required by the bank switcher.');
66	        }
67	        modal.setTitle(getString('switcherselectbank', 'core_question'));
68	
69	        if (currentCmId) {
70	            // Create a 'Go back' button and set it in the footer.
71	            const el = document.createElement('button');
72	            el.classList.add('btn', 'btn-primary');
73	            el.textContent = await getString('switchergoback', 'core_question');
74	            el.setAttribute('data-action', 'go-back');
75	            el.setAttribute('value', currentCmId);
76	            el.addEventListener('click', this.clickListener);
77	            modal.setFooter(el);
78	        }
79	
80	        const params = {
81	            course: courseId,
82	            includeshared: true,
83	            includerecent: true,
84	        };
85	        if (activityCmId) {
86	            params.currentmodule = activityCmId;
87	            params.includeprivate = true;
88	        }
89	        const banksResponse = await Fetch.performGet('question', 'banks', {params});
90	        const {banks} = await banksResponse.json();
91	        const templateContext = {
92	            contextid: contextId,
93	            hasactivitybank: false,
94	            hascoursesharedbanks: false,
95	            coursesharedbanks: [],
96	            hasrecentlyviewedbanks: false,
97	            recentlyviewedbanks: [],
98	        };
99	        banks.forEach((bank) => {
100	            if (bank.current) {
101	                templateContext.hasactivitybank = true;
102	                templateContext.activitybank = {
103	                    name: bank.name,
104	                    cmid: bank.modid,
105	                };
106	                return;
107	            }
108	            if (bank.recent) {
109	                templateContext.hasrecentlyviewedbanks = true;
110	                templateContext.recentlyviewedbanks.push({
111	                    coursenamebankname: bank.coursenamebankname,
112	                    modid: bank.modid,
113	                });
114	                return;
115	            }
116	            templateContext.hascoursesharedbanks = true;
117	            templateContext.coursesharedbanks.push({
118	                name: bank.name,
119	                modid: bank.modid,
120	            });
121	        });
122	
123	        modal.setBody(
124	            Templates.render('core_question/switch_question_bank', templateContext)
125	        );
126	        const placeholder = await getString('switchersearchbyname', 'core_question');
127	        await modal.getBodyPromise();
128	        await AutoComplete.enhance(
129	            SELECTORS.BANK_SEARCH,
130	            false,
131	            'core_question/question_banks_datasource',
132	            placeholder,
133	            false,
134	            true,
135	            '',
136	            true
137	        );
138	
139	        const modalBody = modal.getBody()[0];
140	        // Hide the selection element as we don't need it.
141	        modalBody.querySelector(SELECTORS.AUTOCOMPLETE_SELECTION)?.classList.add('d-none');
142	
143	        const switcherElement = modalBody.querySelector(SELECTORS.BANK_SWITCHER);
144	        switcherElement.addEventListener('click', this.clickListener);
145	        switcherElement.addEventListener('change', this.changeListener);
146	    }
147	
148	    clickListener(e) {
149	        const goBack = e.target.closest(SELECTORS.GO_BACK_BUTTON);
150	        let cmid;
151	        if (goBack) {
152	            cmid = goBack.value;
153	        } else {
154	            const anchor = e.target.closest(SELECTORS.ANCHOR);
155	            if (!anchor) {
156	                return;
157	            }
158	            cmid = anchor.dataset.newmodid;
159	        }
160	        e.preventDefault();
161	        const modalElement = e.target.closest(SELECTORS.MODAL);
162	        const bankSwitched = new CustomEvent('bankSwitched', {detail: {cmid}});
163	        modalElement.dispatchEvent(bankSwitched);
164	    }
165	
166	    changeListener(e) {
167	        const search = e.target.closest(SELECTORS.BANK_SEARCH);
168	        if (!search) {
169	            return;
170	        }
171	        const bankCmId = search.value;
172	        if (bankCmId > 0) {
173	            const modalElement = e.target.closest(SELECTORS.MODAL);
174	            const bankSwitched = new CustomEvent('bankSwitched', {detail: {cmid: bankCmId}});
175	            modalElement.dispatchEvent(bankSwitched);
176	        }
177	    }
178	}
