234	    protected function build_query(): void {
235	        // Get the required tables and fields.
236	        [$fields, $joins] = $this->get_component_requirements(array_merge($this->requiredcolumns, $this->questionactions));
237	
238	        // Build the order by clause.
239	        $sorts = [];
240	        foreach ($this->sort as $sortname => $sortorder) {
241	            [$colname, $subsort] = $this->parse_subsort($sortname);
242	            $sorts[] = $this->requiredcolumns[$colname]->sort_expression($sortorder == SORT_DESC, $subsort);
243	        }
244	
245	        // Build the where clause.
246	        // An additional condition is required in the subquery to account for scenarios
247	        // where the latest version is hidden. This ensures we retrieve the previous
248	        // "Ready" version instead of the hidden latest version.
249	        $onlyready = '((qv.status = :status))';
250	        $this->sqlparams['status'] = question_version_status::QUESTION_STATUS_READY;
251	        $conditions = [];
252	        foreach ($this->searchconditions as $searchcondition) {
253	            if ($searchcondition->where()) {
254	                $conditions[] = '((' . $searchcondition->where() .'))';
255	            }
256	            if ($searchcondition->params()) {
257	                $this->sqlparams = array_merge($this->sqlparams, $searchcondition->params());
258	            }
259	        }
260	        $latestversion = 'qv2.questionbankentryid IS NULL';
261	        $majorconditions = ['q.parent = :parent', $latestversion, $onlyready];
262	        $this->sqlparams = array_merge(['parent' => 0], $this->sqlparams);
263	        // Get higher level filter condition.
264	        $jointype = isset($this->pagevars['jointype']) ? (int)$this->pagevars['jointype'] : condition::JOINTYPE_DEFAULT;
265	        $nonecondition = ($jointype === datafilter::JOINTYPE_NONE) ? ' NOT ' : '';
266	        $separator = ($jointype === datafilter::JOINTYPE_ALL) ? ' AND ' : ' OR ';
267	        // Build the SQL.
268	        $this->sqlparams['substatus'] = question_version_status::QUESTION_STATUS_HIDDEN;
269	        $sql = '      FROM {question} q ' . implode(' ', $joins) .
270	               ' LEFT JOIN {question_versions} qv2 ON (   qv2.questionbankentryid = qv.questionbankentryid
271	                                                      AND qv2.version > qv.version
272	                                                      AND qv2.status <> :substatus
273	                                                      )';
274	        $sql .= ' WHERE ' . implode(' AND ', $majorconditions);
275	        if (!empty($conditions)) {
276	            $sql .= ' AND ' . $nonecondition . ' ( ';
277	            $sql .= implode($separator, $conditions);
278	            $sql .= ' ) ';
279	        }
280	        $this->countsql = 'SELECT count(1)' . $sql;
281	        $this->loadsql = 'SELECT ' . implode(', ', $fields) . $sql . ' ORDER BY ' . implode(', ', $sorts);
282	    }
