293	                }
294	                $pluginobjects = $pluginentrypointobject->get_question_filters($this);
295	                foreach ($pluginobjects as $pluginobject) {
296	                    $this->add_searchcondition($pluginobject, $pluginobject->get_condition_key());
297	                }
