885	    /**
886	     * Shows the question bank interface.
887	     */
888	    public function display(): void {
889	        $editcontexts = $this->contexts->having_one_edit_tab_cap('questions');
890	
891	        echo \html_writer::start_div('questionbankwindow boxwidthwide boxaligncenter', [
892	            'data-component' => 'core_question',
893	            'data-callback' => 'display_question_bank',
894	            'data-contextid' => $editcontexts[array_key_last($editcontexts)]->id,
895	        ]);
896	
897	        // Show the filters and search options.
898	        $this->wanted_filters();
899	        // Continues with list of questions.
900	        $this->display_question_list();
901	        echo \html_writer::end_div();
902	
903	    }
