905	    /**
906	     * The filters for the question bank.
907	     */
908	    public function wanted_filters(): void {
909	        global $OUTPUT;
910	        [, $contextid] = explode(',', $this->pagevars['cat']);
911	        $catcontext = \context::instance_by_id($contextid);
912	        // Category selection form.
913	        $this->display_question_bank_header();
914	        // Add search conditions.
915	        $this->add_standard_search_conditions();
916	        // Render the question bank filters.
917	        $additionalparams = [
918	            'perpage' => $this->pagevars['qperpage'],
919	        ];
920	        $filter = new question_bank_filter_ui($catcontext, $this->searchconditions, $additionalparams, $this->component,
921	                $this->callback, static::class, 'qbank-table', $this->cm?->id, $this->pagevars,
922	                $this->extraparams);
923	        echo $OUTPUT->render($filter);
924	    }
