926	    /**
927	     * Display the header element for the question bank.
928	     */
929	    protected function display_question_bank_header(): void {
930	        global $OUTPUT;
931	        echo $OUTPUT->heading(get_string('questionbank', 'question'), 2);
932	    }
933	
934	    /**
935	     * Does the current view allow adding new questions?
936	     *
937	     * @return bool True if the view supports adding new questions.
938	     */
939	    public function allow_add_questions(): bool {
940	        return true;
941	    }
942	
943	    /**
944	     * Output the question bank controls for each plugin.
945	     *
946	     * Controls will be output in the order defined by the array keys returned from
947	     * {@see plugin_features_base::get_question_bank_controls}. If more than one plugin defines a control in the same position,
948	     * they will placed after one another based on the alphabetical order of the plugins.
949	     *
950	     * @param \core\context $context The current context, for permissions checks.
951	     * @param int $categoryid The current question category.
952	     */
953	    protected function get_plugin_controls(\core\context $context, int $categoryid): string {
954	        global $OUTPUT;
955	        $orderedcontrols = [];
956	        foreach ($this->plugins as $plugin) {
957	            $plugincontrols = $plugin->get_question_bank_controls($this, $context, $categoryid);
958	            foreach ($plugincontrols as $position => $plugincontrol) {
959	                if (!array_key_exists($position, $orderedcontrols)) {
960	                    $orderedcontrols[$position] = [];
961	                }
962	                $orderedcontrols[$position][] = $plugincontrol;
963	            }
964	        }
965	        ksort($orderedcontrols);
966	        $output = '';
967	        foreach ($orderedcontrols as $controls) {
968	            foreach ($controls as $control) {
969	                $output .= $OUTPUT->render($control);
970	            }
971	        }
972	        return $OUTPUT->render_from_template('core_question/question_bank_controls', ['controls' => $output]);
973	    }
974	
975	    /**
976	     * Prints the table of questions in a category with interactions
977	     */
978	    public function display_question_list(): void {
979	        // This function can be moderately slow with large question counts and may time out.
980	        // We probably do not want to raise it to unlimited, so randomly picking 5 minutes.
981	        // Note: We do not call this in the loop because quiz ob_ captures this function (see raise() PHP doc).
982	        \core_php_time_limit::raise(300);
983	        raise_memory_limit(MEMORY_EXTRA);
984	
985	        [$categoryid, $contextid] = category_condition::validate_category_param($this->pagevars['cat']);
986	        $catcontext = \context::instance_by_id($contextid);
987	        // Update the question in the list with correct category context when we have selected category filter.
988	        if (isset($this->pagevars['filter']['category']['values'])) {
989	            $categoryid = $this->pagevars['filter']['category']['values'][0];
990	            foreach ($this->contexts->all() as $context) {
991	                if ((int) $context->instanceid === (int) $categoryid) {
992	                    $catcontext = $context;
993	                    break;
994	                }
995	            }
996	        }
997	
998	        echo \html_writer::start_tag(
999	            'div',
1000	            [
1001	                'id' => 'questionscontainer',
1002	                'data-component' => $this->component,
1003	                'data-callback' => $this->callback,
1004	                'data-contextid' => $this->get_most_specific_context()->id,
1005	            ]
1006	        );
1007	        echo $this->get_plugin_controls($catcontext, $categoryid);
1008	
1009	        $questions = $this->load_questions();
1010	
1011	        // This html will be refactored in the bulk actions implementation.
1012	        echo \html_writer::start_tag('form', ['action' => $this->baseurl, 'method' => 'post', 'id' => 'questionsubmit']);
1013	        echo \html_writer::start_tag('fieldset', ['class' => 'invisiblefieldset', 'style' => "display: block;"]);
1014	        echo \html_writer::empty_tag('input', ['type' => 'hidden', 'name' => 'sesskey', 'value' => sesskey()]);
1015	        echo \html_writer::empty_tag('input', ['type' => 'hidden', 'name' => 'addonpage']);
1016	        echo \html_writer::input_hidden_params($this->baseurl);
1017	
1018	        $filtercondition = json_encode($this->get_pagevars());
1019	        // Embeded filterconditon into the div.
1020	        echo \html_writer::start_tag('div',
