755	     * Generates the table of summarydata
756	     *
757	     * @param quiz_attempt $attemptobj
758	     * @param display_options $displayoptions
759	     */
760	    public function summary_table($attemptobj, $displayoptions) {
761	        // Prepare the summary table header.
762	        $table = new html_table();
763	        $table->attributes['class'] = 'table generaltable table-striped quizsummaryofattempt table-hover';
764	        $table->head = [get_string('question', 'quiz'), get_string('status', 'quiz')];
765	        $table->align = ['left', 'left'];
766	        $table->size = ['', ''];
767	        $markscolumn = $displayoptions->marks >= question_display_options::MARK_AND_MAX;
768	        if ($markscolumn) {
769	            $table->head[] = get_string('marks', 'quiz');
770	            $table->align[] = 'left';
771	            $table->size[] = '';
772	        }
773	        $tablewidth = count($table->align);
774	        $table->data = [];
775	
776	        // Get the summary info for each question.
777	        $slots = $attemptobj->get_slots();
778	        foreach ($slots as $slot) {
779	            // Add a section headings if we need one here.
780	            $heading = $attemptobj->get_heading_before_slot($slot);
781	            if ($heading !== null) {
782	                // There is a heading here.
783	                $rowclasses = 'quizsummaryheading';
784	                if ($heading) {
785	                    $heading = format_string($heading);
786	                } else {
787	                    if (count($attemptobj->get_quizobj()->get_sections()) > 1) {
788	                        // If this is the start of an unnamed section, and the quiz has more
789	                        // than one section, then add a default heading.
790	                        $heading = get_string('sectionnoname', 'quiz');
791	                        $rowclasses .= ' dimmed_text';
792	                    }
793	                }
794	                $cell = new html_table_cell(format_string($heading));
795	                $cell->header = true;
796	                $cell->colspan = $tablewidth;
797	                $table->data[] = [$cell];
798	                $table->rowclasses[] = $rowclasses;
799	            }
800	
801	            // Don't display information items.
802	            if (!$attemptobj->is_real_question($slot)) {
803	                continue;
804	            }
805	
