{{!
    @template qbank_managecategories/categories_header

    Template for displaying category view.

    Context variables required for this template:
    * helpstringhead - String header accompanied with it help button.
    * hascapability - Boolean, true if user has capability to add categories.
    * checkbox - Checkbox displaying descriptions.
    * contextid - Context id for js init.
    * cmid - Course module id, if in a plugin.

    Example context (json):
    {
        "helpstringhead": "<h2> Edit categories <a href='someurl'>...</a></h2>",
        "hascapability": true,
        "checkbox": "<form>...</form>",
        "contextid": "18",
        "cmid": "1234",
        "courseid": "1234"
    }
}}
<div>
    <div>
        {{{helpstringhead}}}
    </div>
</div>
<div class="d-flex">
    {{#hascapability}}
        {{>qbank_managecategories/addcategory}}
    {{/hascapability}}
    {{#showdescriptions}}
        {{>qbank_managecategories/showdescriptions}}
    {{/showdescriptions}}
</div>

        $filtertypes = [];

        foreach ($this->searchconditions as $searchcondition) {
            $filtertypes[] = $this->get_filter_object(
                $searchcondition->get_condition_key(),
                $searchcondition->get_title(),
                $searchcondition->allow_custom(),
                $searchcondition->allow_multiple(),
                $searchcondition->get_filter_class(),
                $searchcondition->get_initial_values(),
                $searchcondition->allow_empty(),
                $searchcondition->get_filteroptions(),
                $searchcondition->is_required(),
                $searchcondition->get_join_list(),
            );
        }

        return $filtertypes;
    }

    /**
     * Export the renderer data in a mustache template friendly format.
     *
     * @param renderer_base $output Unused.
     * @return stdClass Data in a format compatible with a mustache template.
     */
    public function export_for_template(renderer_base $output): stdClass {
        $defaultcategory = question_get_default_category($this->context->id, true);

        if ($this->context->contextlevel != CONTEXT_MODULE) {
            debugging("Context level: {$this->context->contextlevel} is now deprecated, please use CONTEXT_MODULE");
        }

        $courseid = $this->context->get_course_context()->instanceid;

        return (object) [
            'tableregionid' => $this->tableregionid,
            'courseid' => $courseid,
            'filtertypes' => $this->get_filtertypes(),
            'selected' => 'category',
            'rownumber' => 1,
            'categoryid' => $defaultcategory->id,
            'perpage' => $this->additionalparams['perpage'] ?? 0,
            'contextid' => $this->context->id,
            'quizcmid' => $this->extraparams['quizcmid'] ?? $this->cmid,
            'component' => $this->component,
            'callback' => $this->callback,
            'view' => $this->view,
            'cmid' => $this->cmid ?? 0,
            'pagevars' => json_encode($this->pagevars),
            'extraparams' => json_encode($this->extraparams),
            'showallbutton' => true,
        ];
    }
}

